// scripts/sync-app-assets.js — push the built app assets into the Xcode project.
//
//   npm run app:sync        (after `node build.js`, and after ANY regeneration of
//                            safari-project/ — see docs/release-checklist.md)
//
// `safari-project/` is gitignored and disposable: it gets regenerated by
// `safari-web-extension-converter`, which resets the project's file list, version,
// bundle ids and team. Nothing that matters may live there only. So the app's real
// source is `app/` in the repo, `build/app-bundle.js` builds it to `dist-app/`, and
// this script copies it in.
//
// The assets get written, and so does every place the converter's template assumes
// something our app is not. The patches are easy to forget precisely because each one
// looks like a layout bug rather than a one-line setting:
//
//   1. `Main.html` / `Script.js` / `Style.css` — the three filenames the converter's
//      App target ALREADY references, so the pbxproj never needs touching.
//   2. `ViewController.swift` — scrolling (the template is one non-scrolling screen,
//      a review list is not) and the iOS media user-gesture gate.
//   3. `Info.plist` — the microphone usage string the 说 exercise needs, and the iOS
//      App's `UIBackgroundModes: audio` (播客模式 §9.5 background playback).
//   4. `project.pbxproj` — the macOS audio-input sandbox entitlement.
//   5. the macOS `Main.storyboard` — a window the user can actually resize, and a
//      menu bar with an Edit menu, without which ⌘V does not paste.
//   6. `ViewController.swift` again — `app/native/audio-bridge.swift` pasted in as a
//      marker-delimited block (§9.5's native half: audio session + media remote).
//
// Each is written against the converter's template shape and is idempotent.
//
// Idempotent: safe to run repeatedly, and a no-op patch is reported as such.

'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
// 每个工程灌**它自己 flavor** 的宿主 App 包。以前只有一个 `dist-app/`，两棵树都灌它，
// 于是中国版 App 带的是国际版引擎注册表 —— 设置页列出 ChatGPT / Claude / Google，而它
// 旁边的中国版扩展早就把这些滤掉了。同一个产品两套标准，1.6.4 就这么出货了。
// 来源必须跟着 flavor 走，而不是跟着「有哪个目录」走。
const APP_SRC = {
  'safari-project': 'dist-app',
  'safari-project-china': 'dist-app-china',
  'safari-project-macos': 'dist-app',
};
const FILES = ['Main.html', 'Script.js', 'Style.css'];

// Every project the converter can produce. A flavor that exists but is not listed
// here would silently keep stale assets, so missing ones are reported, not skipped.
const PROJECTS = ['safari-project', 'safari-project-china', 'safari-project-macos'];

// Every patch below is written against the converter's DUAL-platform layout
// (`Shared (App)` beside `iOS (App)` / `macOS (App)`). `--macos-only` produces a
// different, flat one, and the old code just looked for `Shared (App)`, found
// nothing, and said "未生成，跳过" — which reads as "there is no project" when the
// project is sitting right there. Nothing patched it for months: the shipped macOS
// 1.4.1 (14) host app carried the converter's 979-byte template Main.html instead of
// our 19543-byte learning app, and no output ever said so.
//
// So the three states are now distinct, and only one of them is silent:
//   absent       — nothing generated yet. Fine, skip.
//   ok           — dual layout found. Patch it.
//   unrecognized — a project IS there but has no `Shared (App)`. Hard failure:
//                  patching it is exactly what we cannot do, so saying nothing is
//                  the one unacceptable answer.
function classifyProject(projRoot) {
  if (!fs.existsSync(projRoot)) return { state: 'absent', dirs: [] };
  const dirs = [];
  for (const name of fs.readdirSync(projRoot)) {
    const shared = path.join(projRoot, name, 'Shared (App)');
    if (fs.existsSync(shared)) dirs.push(shared);
  }
  return dirs.length ? { state: 'ok', dirs } : { state: 'unrecognized', dirs: [] };
}

function patchViewController(sharedDir) {
  const f = path.join(sharedDir, 'ViewController.swift');
  if (!fs.existsSync(f)) return 'no ViewController.swift';
  let src = fs.readFileSync(f, 'utf8');
  const notes = [];

  // Patch 1: the converter template is a single non-scrolling screen; the
  // review list is not.
  const SCROLL_NEEDLE = 'self.webView.scrollView.isScrollEnabled = false';
  if (src.includes(SCROLL_NEEDLE)) {
    src = src.replace(SCROLL_NEEDLE,
      '// Patched by scripts/sync-app-assets.js — the converter template is a single\n'
      + '        // non-scrolling screen; the review list is not.\n'
      + '        self.webView.scrollView.isScrollEnabled = true');
    notes.push('scroll patched');
  } else {
    notes.push(src.includes('isScrollEnabled = true') ? 'scroll already patched' : 'scroll: nothing to patch');
  }

  // Patch 2: lift WKWebView's media user-gesture gate. The default policy only
  // allows play() inside a gesture's SYNCHRONOUS call stack, but the review
  // page's speech playback is inherently "tap → async fetch/synthesis →
  // play()" — first plays of a card were always rejected (surfaced as
  // `blocked`), cache hits raced the gesture window and worked only sometimes.
  //
  // The web view must be RECREATED with the configuration: the storyboard
  // instance copied its configuration at init, and mutating it afterwards is
  // silently ignored (proved on-device 2026-08-09 — an in-place
  // `webView.configuration.mediaTypes... = []` left the gate up). This is our
  // own page; auto-read is a feature, not third-party abuse.
  const MEDIA_LINE = 'mediaTypesRequiringUserActionForPlayback';
  const VDL_ANCHOR = 'super.viewDidLoad()\n\n        self.webView.navigationDelegate = self';
  if (src.includes(MEDIA_LINE)) {
    notes.push('media gate already patched');
  } else if (src.includes(VDL_ANCHOR)) {
    src = src.replace(VDL_ANCHOR,
      'super.viewDidLoad()\n\n'
      + '#if os(iOS)\n'
      + '        // Patched by scripts/sync-app-assets.js — lift the media user-gesture\n'
      + '        // gate. The storyboard web view copied its configuration at init, so it\n'
      + '        // must be recreated with the configuration the review page needs:\n'
      + '        // speech playback is "tap → async fetch → play()", which the default\n'
      + '        // policy rejects; auto-read is a feature here.\n'
      + '        let mtConf = WKWebViewConfiguration()\n'
      + '        mtConf.allowsInlineMediaPlayback = true\n'
      + '        mtConf.mediaTypesRequiringUserActionForPlayback = []\n'
      + '        let mtFresh = WKWebView(frame: self.webView.frame, configuration: mtConf)\n'
      + '        mtFresh.autoresizingMask = [.flexibleWidth, .flexibleHeight]\n'
      + '        self.webView.superview?.addSubview(mtFresh)\n'
      + '        self.webView.removeFromSuperview()\n'
      + '        self.webView = mtFresh\n'
      + '#endif\n\n'
      + '        self.webView.navigationDelegate = self');
    notes.push('media gate patched (web view recreated)');
  } else {
    notes.push('media gate: viewDidLoad anchor missing');
  }

  // Patch 8 (§9.5 播客模式): keep the screen awake. A driving session is
  // continuous foreground audio with no touches; the default idle timer locks
  // the phone mid-card and (with no background audio session) kills the speech.
  // App-wide, not per-mode, on purpose: a per-mode toggle needs a JS↔Swift
  // message bridge, which grows the Swift patch surface the converter
  // regenerates (learning-design §12). This is a study app the user opened —
  // same shape as a navigation app keeping its screen on.
  const IDLE_NEEDLE = 'isIdleTimerDisabled';
  if (src.includes(IDLE_NEEDLE)) {
    notes.push('idle timer already patched');
  } else if (src.includes('self.webView.navigationDelegate = self')) {
    src = src.replace('self.webView.navigationDelegate = self',
      'self.webView.navigationDelegate = self\n'
      + '#if os(iOS)\n'
      + '        // Patched by scripts/sync-app-assets.js — 播客模式 (§9.5) is continuous\n'
      + '        // foreground audio with no touches; the idle timer would lock the phone\n'
      + '        // mid-card and stop the speech.\n'
      + '        UIApplication.shared.isIdleTimerDisabled = true\n'
      + '#endif');
    notes.push('idle timer patched');
  } else {
    notes.push('idle timer: anchor missing');
  }

  // Patch 9 (§9.5 后台/锁屏): hand the web view to the native audio bridge. Both
  // platforms — iOS needs the audio session, macOS needs the media remote (its
  // process is never suspended, so background playback is unconditional there).
  //
  // A SECOND channel, deliberately: the converter's own `controller` handler has its
  // entire body inside `#if os(macOS)` and opens with `message.body as! String`, so a
  // dictionary body would trap. Reusing it would mean editing converter code we do
  // not own; `mtAudio` keeps every byte of routing inside the marker block.
  const BRIDGE_NEEDLE = 'MTAudioBridge.shared.install';
  const BRIDGE_ANCHOR = 'self.webView.configuration.userContentController.add(self, name: "controller")';
  if (src.includes(BRIDGE_NEEDLE)) {
    notes.push('audio bridge install already patched');
  } else if (src.includes(BRIDGE_ANCHOR)) {
    src = src.replace(BRIDGE_ANCHOR, BRIDGE_ANCHOR + '\n\n'
      + '        // Patched by scripts/sync-app-assets.js — 播客模式 (§9.5) 的后台/锁屏播放。\n'
      + '        MTAudioBridge.shared.install(webView: self.webView)');
    notes.push('audio bridge install patched');
  } else {
    notes.push('✗ audio bridge install: userContentController.add 锚点缺失');
  }

  fs.writeFileSync(f, src);
  return notes.join(' · ');
}

// Patch 10 (§9.5 后台/锁屏): paste `app/native/audio-bridge.swift` into
// ViewController.swift as a marker-delimited block.
//
// Marker block, not a needle. Every other patch here is one constant line, where
// "contains it? then skip" is right. This block will keep evolving, and a needle
// check would freeze whatever version first reached a given tree while `app:sync`
// cheerfully printed "already patched" forever. Replacing the whole block makes
// idempotence a RESULT (same template ⇒ same bytes) instead of a special case.
//
// Anchored after `import WebKit` rather than appended at the end of the file, which
// buys three things at once: the template's own `import AVFoundation` / `import
// MediaPlayer` are part of the block, so "keep the imports idempotent" stops being a
// separate problem; there is a real anchor to fail loudly on; and that import line is
// identical across both flavors and both platforms.
const BRIDGE_BEGIN = '// ─── BEGIN mt-audio-bridge (generated — do not edit here) ───';
const BRIDGE_END = '// ─── END mt-audio-bridge ───';
const BRIDGE_IMPORT_ANCHOR = /^import WebKit$/m;

function patchAudioBridgeSwift(src, tpl) {
  const block = [
    BRIDGE_BEGIN,
    '// Source: app/native/audio-bridge.swift · written by scripts/sync-app-assets.js.',
    '// Edit the repo file and re-run `npm run app:sync`; edits made here are overwritten.',
    tpl.replace(/\s+$/, ''),
    BRIDGE_END,
  ].join('\n');

  const b = src.indexOf(BRIDGE_BEGIN);
  const e = src.indexOf(BRIDGE_END);
  // Half a pair means someone hand-edited or the file was truncated. Appending a
  // second copy would give the target two `MTAudioBridge` types, and the compiler
  // error for that points nowhere near the cause. Refuse instead.
  if ((b < 0) !== (e < 0)) return { swift: src, note: '✗ audio bridge: 标记不成对，拒绝改写' };
  if (b >= 0 && e < b) return { swift: src, note: '✗ audio bridge: 标记顺序颠倒，拒绝改写' };

  let out;
  if (b >= 0) {
    const tail = e + BRIDGE_END.length + (src[e + BRIDGE_END.length] === '\n' ? 1 : 0);
    out = src.slice(0, b) + block + '\n' + src.slice(tail);
  } else {
    if (!BRIDGE_IMPORT_ANCHOR.test(src)) {
      return { swift: src, note: '✗ audio bridge: import WebKit 锚点缺失 — 转换器模板变了？' };
    }
    out = src.replace(BRIDGE_IMPORT_ANCHOR, 'import WebKit\n\n' + block + '\n');
  }
  if (out === src) return { swift: src, note: 'audio bridge already current' };
  return { swift: out, note: b >= 0 ? 'audio bridge block replaced' : 'audio bridge block inserted' };
}

function patchAudioBridge(sharedDir) {
  const tplPath = path.join(ROOT, 'app', 'native', 'audio-bridge.swift');
  if (!fs.existsSync(tplPath)) return '✗ audio bridge: app/native/audio-bridge.swift 不存在';
  const f = path.join(sharedDir, 'ViewController.swift');
  if (!fs.existsSync(f)) return '✗ audio bridge: no ViewController.swift';
  const { swift, note } = patchAudioBridgeSwift(
    fs.readFileSync(f, 'utf8'), fs.readFileSync(tplPath, 'utf8'));
  if (!/^✗/.test(note)) fs.writeFileSync(f, swift);
  return note;
}

// Patch 3 (§9.4): the 说 exercise records the microphone inside the WKWebView.
// iOS requires NSMicrophoneUsageDescription in the APP target's Info.plist or the
// process is killed at getUserMedia time — and the converter's template does not
// carry it. `safari-project*/` is regenerated (and this key wiped) routinely, so
// the patch lives here, like every other thing the converter gets wrong for us.
// The string names the §10 Gate C contract, not a generic "needs the mic".
//
const MIC_KEY = 'NSMicrophoneUsageDescription';
const MIC_TEXT = '朗读练习需要使用麦克风录音；录音只发送到你自己配置的转写端点，识别后立即丢弃，绝不存储或上传到我们的服务器。';

// One row per declaration. `only` names the platform App directory it belongs to;
// absent means every App target.
//
// `UIBackgroundModes` MUST be iOS-only, and it cannot ride `build-safari.sh`'s
// `set_app_key` to get there: that helper anchors on
// `PRODUCT_BUNDLE_IDENTIFIER = $BUNDLE_ID;`, and the perl line beside it rewrites
// EVERY bundle id in the project to the same value on purpose (one App Store record,
// two platforms) — so the setting would land on the macOS App target too. A macOS app
// declaring a background mode it cannot use is something review asks about, and
// macOS needs nothing here anyway: its process is never suspended (§9.5).
const PLIST_KEYS = [
  { key: MIC_KEY, xml: `<string>${MIC_TEXT}</string>` },
  { key: 'UIBackgroundModes', only: 'iOS (App)',
    xml: '<array>\n\t\t<string>audio</string>\n\t</array>' },
];

// Pure, so the tests can run it without an Xcode tree. Returns { xml, added, note }.
function patchPlistXml(src, keys) {
  const added = [];
  let out = src;
  for (const k of keys) {
    if (out.includes(`<key>${k.key}</key>`)) continue;
    const anchor = out.lastIndexOf('</dict>');
    if (anchor < 0) return { xml: src, added: [], note: '✗ no </dict> anchor' };
    out = out.slice(0, anchor) + `\t<key>${k.key}</key>\n\t${k.xml}\n` + out.slice(anchor);
    added.push(k.key);
  }
  return { xml: out, added, note: added.length ? `patched ${added.join(', ')}` : 'already current' };
}

function patchInfoPlists(sharedDir) {
  const appRoot = path.dirname(sharedDir);   // …/<name>/, holding "iOS (App)" etc.
  const notes = [];
  for (const entry of fs.readdirSync(appRoot)) {
    if (!/\(App\)$/.test(entry) || entry.startsWith('Shared')) continue;
    const plist = path.join(appRoot, entry, 'Info.plist');
    if (!fs.existsSync(plist)) continue;
    const keys = PLIST_KEYS.filter((k) => !k.only || k.only === entry);
    const { xml, note } = patchPlistXml(fs.readFileSync(plist, 'utf8'), keys);
    if (/^✗/.test(note)) { notes.push(`✗ ${entry}: ${note.slice(2)}`); continue; }
    fs.writeFileSync(plist, xml);
    notes.push(entry + ': ' + note);
  }
  return notes.length ? notes.join(' · ') : 'no app Info.plist found';
}

// Patch 4 (§9.4): the sandboxed macOS App also needs the audio-input sandbox
// entitlement, or getUserMedia is denied regardless of the Info.plist string. The
// converter uses Xcode 15+ build-settings-based entitlements (no .entitlements
// file — `ENABLE_APP_SANDBOX = YES` in the pbxproj), so the grant is the sibling
// build setting `ENABLE_RESOURCE_ACCESS_AUDIO_INPUT`, inserted ONLY into build
// configurations that belong to the macOS APP target (matched by its
// INFOPLIST_FILE — the extension target never records audio and stays ungranted).
// Idempotent, like every patch here; regeneration wipes it, app:sync restores it.
function patchPbxproj(sharedDir) {
  const appRoot = path.dirname(sharedDir);
  const xcodeproj = fs.readdirSync(appRoot).find((n) => n.endsWith('.xcodeproj'));
  if (!xcodeproj) return 'no xcodeproj';
  const f = path.join(appRoot, xcodeproj, 'project.pbxproj');
  if (!fs.existsSync(f)) return 'no project.pbxproj';
  let src = fs.readFileSync(f, 'utf8');
  if (src.includes('ENABLE_RESOURCE_ACCESS_AUDIO_INPUT')) return 'audio-input entitlement already patched';
  // The sandbox line and the INFOPLIST_FILE line that identifies the target sit a
  // few (alphabetically sorted) settings apart — match the span WITHIN one build
  // configuration block (no `}` may intervene), so an extension target's sandbox
  // line can never borrow the app target's identifier line.
  const NEEDLE = /ENABLE_APP_SANDBOX = YES;((?:\n[^\n}]*){0,10}?\n\s*INFOPLIST_FILE = "macOS \(App\)\/Info\.plist";)/g;
  let hits = 0;
  src = src.replace(NEEDLE, (m, tail) => {
    hits++;
    return 'ENABLE_APP_SANDBOX = YES;\n\t\t\t\tENABLE_RESOURCE_ACCESS_AUDIO_INPUT = YES;' + tail;
  });
  if (!hits) return 'audio-input: macOS (App) sandbox block not found — converter layout changed?';
  fs.writeFileSync(f, src);
  return `audio-input entitlement patched (${hits} configs)`;
}

// Patch 5: the macOS host window. The converter's storyboard gives it
// `styleMask titled+closable` and nothing else — no resize, no zoom, no
// miniaturize — plus `fullScreenNone`, at a fixed 425×325. That is a sane window
// for what the template puts inside it (the 979-byte "this is your extension"
// placeholder). It is the wrong window for a reading app.
//
// Nobody saw it for three releases because nobody could see the content either:
// the same tree that never got its resources (see classifyProject above) shipped
// the placeholder, and a placeholder does not care how big it is. build 16 put
// the real review app in that window for the first time, and the smoke test
// walked straight into a 425pt box the user cannot enlarge — no drag, no zoom,
// not even full screen.
//
// Only the window is wrong: the wkWebView already carries
// `widthSizable/heightSizable`, so it follows the frame once the frame can move.
//
// The three template rects (contentRect, the view, the web view) all agree on
// the same size, and IB keeps them in sync when a human resizes the window — so
// the patch reads the size off contentRect and moves all of them together,
// instead of hardcoding a number the converter is free to change.
const WIN_W = 820;
const WIN_H = 640;
function patchMacWindowXml(src) {
  const STYLE_RE = /<windowStyleMask key="styleMask"((?:\s+[\w-]+="[^"]*")*)\s*\/>/;
  const style = src.match(STYLE_RE);
  if (!style) return { xml: src, note: 'window: styleMask not found — converter layout changed?' };
  if (/\bresizable="YES"/.test(style[1])) return { xml: src, note: 'window already patched' };

  const notes = [];
  // Keep whatever the converter set, add what a document window needs.
  let out = src.replace(STYLE_RE,
    `<windowStyleMask key="styleMask"${style[1]} miniaturizable="YES" resizable="YES"/>`);
  notes.push('resizable');

  const FULLSCREEN_RE = /(<windowCollectionBehavior key="collectionBehavior")\s+fullScreenNone="YES"\s*\/>/;
  if (FULLSCREEN_RE.test(out)) {
    out = out.replace(FULLSCREEN_RE, '$1 fullScreenPrimary="YES"/>');
    notes.push('fullscreen');
  }

  const rect = out.match(/<rect key="contentRect"[^/]*?width="([\d.]+)" height="([\d.]+)"\s*\/>/);
  if (rect) {
    const w = rect[1].replace(/\./g, '\\.');
    const h = rect[2].replace(/\./g, '\\.');
    // screenRect is a different size, so it is untouched; the view and the web
    // view share the template's content size and move with it.
    out = out.replace(new RegExp(`width="${w}" height="${h}"`, 'g'),
      `width="${WIN_W}" height="${WIN_H}"`);
    notes.push(`${WIN_W}×${WIN_H}`);
  } else {
    notes.push('contentRect not found — size left alone');
  }

  return { xml: out, note: `window patched (${notes.join(' · ')})` };
}

function patchMacWindow(sharedDir) {
  const appRoot = path.dirname(sharedDir);
  const f = path.join(appRoot, 'macOS (App)', 'Base.lproj', 'Main.storyboard');
  if (!fs.existsSync(f)) return 'no macOS storyboard';
  const src = fs.readFileSync(f, 'utf8');
  const { xml, note } = patchMacWindowXml(src);
  if (xml !== src) fs.writeFileSync(f, xml);
  return note;
}

// Patch 6: the macOS menu bar. The converter's storyboard gives the app exactly two
// top-level menus — the app menu and Help — and `AppDelegate.swift` builds none, so
// there is no Edit menu anywhere.
//
// That is not cosmetic. AppKit routes ⌘V as a key equivalent: NSApplication offers it
// to the main menu FIRST, and only a menu item carrying `paste:` claims it. With no
// such item the keystroke falls through as a plain keyDown, and a plain keyDown does
// not paste — WKWebView pastes in response to the `paste:` NSResponder action, which
// nothing ever sends. So ⌘V / ⌘C / ⌘X / ⌘A / ⌘Z are all dead, and ⌘W / ⌘M with them.
//
// It has never hurt a user, because every shipped macOS build so far carried the
// converter's 979-byte placeholder — no text field to paste into. 1.5.0 is the first
// build where it bites, and it bites on the FIRST screen: pasting an email address and
// then a verification code is the whole of onboarding.
//
// The menu is data here, not a 70-line string literal: hand-indented IB XML is where
// this kind of patch rots.
const MAC_MENUS = [
  { title: 'File', items: [
    { title: 'Close', key: 'w', sel: 'performClose:' },
  ] },
  { title: 'Edit', items: [
    { title: 'Undo', key: 'z', sel: 'undo:' },
    { title: 'Redo', key: 'Z', sel: 'redo:', mods: 'shift="YES" command="YES"' },
    { sep: true },
    { title: 'Cut', key: 'x', sel: 'cut:' },
    { title: 'Copy', key: 'c', sel: 'copy:' },
    { title: 'Paste', key: 'v', sel: 'paste:' },
    { title: 'Delete', sel: 'delete:' },
    { sep: true },
    { title: 'Select All', key: 'a', sel: 'selectAll:' },
  ] },
  // systemMenu="window" hands the window list to AppKit, same as the app/help menus.
  { title: 'Window', systemMenu: 'window', items: [
    { title: 'Minimize', key: 'm', sel: 'performMiniaturize:' },
    { title: 'Zoom', sel: 'performZoom:' },
  ] },
];

const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-');

function renderMacMenus(target, pad) {
  const L = [];
  const at = (n, s) => L.push(' '.repeat(pad + n) + s);
  for (const menu of MAC_MENUS) {
    const m = slug(menu.title);
    at(0, `<menuItem title="${menu.title}" id="mt-mi-${m}">`);
    at(4, '<modifierMask key="keyEquivalentModifierMask"/>');
    at(4, `<menu key="submenu" title="${menu.title}"`
      + (menu.systemMenu ? ` systemMenu="${menu.systemMenu}"` : '') + ` id="mt-menu-${m}">`);
    at(8, '<items>');
    let sepN = 0;
    for (const it of menu.items) {
      if (it.sep) { at(12, `<menuItem isSeparatorItem="YES" id="mt-sep-${m}-${++sepN}"/>`); continue; }
      const s = slug(it.title);
      at(12, `<menuItem title="${it.title}"${it.key ? ` keyEquivalent="${it.key}"` : ''} id="mt-it-${m}-${s}">`);
      // Mirror the converter's own convention: a bare keyEquivalent means ⌘, an item
      // with no shortcut still carries an empty mask, and anything else spells it out.
      if (it.mods) at(16, `<modifierMask key="keyEquivalentModifierMask" ${it.mods}/>`);
      else if (!it.key) at(16, '<modifierMask key="keyEquivalentModifierMask"/>');
      at(16, '<connections>');
      at(20, `<action selector="${it.sel}" target="${target}" id="mt-ac-${m}-${s}"/>`);
      at(16, '</connections>');
      at(12, '</menuItem>');
    }
    at(8, '</items>');
    at(4, '</menu>');
    at(0, '</menuItem>');
  }
  return L.join('\n') + '\n';
}

function patchMacMenuXml(src) {
  if (/selector="paste:"/.test(src)) return { xml: src, note: 'menu already patched' };
  const HELP_RE = /^([ \t]*)<menuItem title="Help"/m;
  const anchor = src.match(HELP_RE);
  if (!anchor) return { xml: src, note: 'menu: Help anchor not found — converter layout changed?' };
  // The First Responder object id is generated per project, so read it off an action
  // the converter already wired instead of hardcoding one (same reflex as Patch 5
  // reading the size off contentRect).
  const fr = src.match(/<action selector="terminate:" target="([^"]+)"/);
  if (!fr) return { xml: src, note: 'menu: First Responder target not found — converter layout changed?' };
  const pad = anchor[1].length;
  const xml = src.replace(HELP_RE, renderMacMenus(fr[1], pad) + anchor[1] + '<menuItem title="Help"');
  return { xml, note: `menu patched (${MAC_MENUS.map((m) => m.title).join(' · ')})` };
}

function patchMacMenu(sharedDir) {
  const appRoot = path.dirname(sharedDir);
  const f = path.join(appRoot, 'macOS (App)', 'Base.lproj', 'Main.storyboard');
  if (!fs.existsSync(f)) return 'no macOS storyboard';
  const src = fs.readFileSync(f, 'utf8');
  const { xml, note } = patchMacMenuXml(src);
  if (xml !== src) fs.writeFileSync(f, xml);
  return note;
}


// ─── Patch 7: App 图标 —— 转换器的白框病（2026-08-15 真机截图坐实） ─────────
// safari-web-extension-converter 生成 AppIcon.appiconset 时，把扩展的 128px
// 圆角图标放大后【居中贴在白底画布】上：iOS 主屏图标要求满幅不透明正方形
// （圆角 iOS 自己裁），于是主屏上出现一圈白框，图还是糊的。
// 修法：仓库 app/appicon/ 里存两套定稿 —— ios-1024.png（满幅、不圆角、不透明）
// 与 mac-icon-*（圆角稿 + Apple 网格 824/1024 留白、四角透明，macOS 规范）——
// 每次 app:sync 原样覆写转换器的同名文件。文件名与 Contents.json 保持转换器
// 的命名，所以 pbxproj / json 都不用动。
function patchAppIcon(sharedDir) {
  const iconSrc = path.join(ROOT, 'app', 'appicon');
  if (!fs.existsSync(iconSrc)) return 'appicon: no app/appicon/, skipped';
  const set = path.join(sharedDir, 'Assets.xcassets', 'AppIcon.appiconset');
  if (!fs.existsSync(set)) return 'appicon: no AppIcon.appiconset';
  let n = 0;
  fs.copyFileSync(path.join(iconSrc, 'ios-1024.png'), path.join(set, 'universal-icon-1024@1x.png')); n++;
  for (const f of fs.readdirSync(iconSrc)) {
    if (!f.startsWith('mac-icon-')) continue;
    fs.copyFileSync(path.join(iconSrc, f), path.join(set, f)); n++;
  }
  return `appicon replaced (${n} files, full-bleed iOS + margined mac)`;
}

function main() {
  let touched = 0;
  // Notes that start with ✗ are failures, and they used to disappear into the middle
  // of a ✓ line. For the §9.5 patches that is not survivable: a missing background
  // patch produces an app that installs fine and goes silent the moment the screen
  // locks — indistinguishable from the feature not being built. Collect and exit 1.
  // Only the new patches emit ✗; the older ones keep their soft wording so a
  // half-generated tree does not start failing for unrelated reasons.
  const problems = [];
  const loud = (proj, label, note) => {
    if (/^✗/.test(note)) problems.push(`${proj} · ${label}: ${note.replace(/^✗\s*/, '')}`);
    return note;
  };
  for (const proj of PROJECTS) {
    const { state, dirs } = classifyProject(path.join(ROOT, proj));
    if (state === 'absent') { console.log(`  – ${proj}: 未生成，跳过`); continue; }
    // 源目录按工程决定，且**缺了就停**，不回落到另一个 flavor 的包 —— 回落正是上一版
    // 出问题的形状：中国版工程拿到了国际版资源，而全程没有一行警告。
    const SRC = path.join(ROOT, APP_SRC[proj]);
    if (!fs.existsSync(SRC)) {
      console.error(`✗ ${proj} 需要 ${APP_SRC[proj]}/，但它不存在`);
      console.error(`  跑 node build.js${APP_SRC[proj].endsWith('-china') ? ' --flavor china' : ''} 先出这个 flavor 的宿主 App 包`);
      process.exit(1);
    }
    for (const f of FILES) {
      if (!fs.existsSync(path.join(SRC, f))) {
        console.error(`✗ ${APP_SRC[proj]}/${f} 缺失 —— 宿主 App 包没构建完整`);
        process.exit(1);
      }
    }
    if (state === 'unrecognized') {
      console.error(`✗ ${proj}/ 存在，但里面找不到 "Shared (App)" —— 这个工程无法打补丁。`);
      console.error('  这是单平台的扁平布局（--ios-only / --macos-only，或旧版转换器生成的树）。');
      console.error('  它拿不到宿主 App 的资源，也拿不到滚动 / 媒体门 / 麦克风声明 /');
      console.error('  audio-input 四个补丁 —— 装出来的 App 是转换器的模板页，不是我们的 App。');
      console.error(`  修法：删掉重生成 —— rm -rf ${proj} && bash build-safari.sh <flavor> <platform>`);
      console.error('  （现在的脚本一个 flavor 只出一棵双平台树，iOS 与 macOS 共用。）');
      process.exit(1);
    }
    for (const shared of dirs) {
      const res = path.join(shared, 'Resources');
      const lproj = path.join(res, 'Base.lproj');
      if (!fs.existsSync(res)) { console.error(`✗ ${proj}: 没有 Resources/`); process.exit(1); }
      fs.mkdirSync(lproj, { recursive: true });
      // Main.html lives in Base.lproj (localizable); the other two sit beside it in
      // Resources/. That split is the converter's, not ours — matching it is what
      // keeps the pbxproj untouched.
      fs.copyFileSync(path.join(SRC, 'Main.html'), path.join(lproj, 'Main.html'));
      fs.copyFileSync(path.join(SRC, 'Script.js'), path.join(res, 'Script.js'));
      fs.copyFileSync(path.join(SRC, 'Style.css'), path.join(res, 'Style.css'));
      const vc = loud(proj, 'ViewController', patchViewController(shared));
      const bridge = loud(proj, 'audio bridge', patchAudioBridge(shared));
      const plists = loud(proj, 'Info.plist', patchInfoPlists(shared));
      console.log(`  ✓ ${proj}: 资源已灌入 · ViewController ${vc} · ${bridge} · Info.plist ${plists} · pbxproj ${patchPbxproj(shared)} · storyboard ${patchMacWindow(shared)} · ${patchMacMenu(shared)} · ${patchAppIcon(shared)}`);
      touched++;
    }
  }

  if (!touched) {
    console.error('✗ 没有找到任何已生成的 Safari 工程 —— 先跑 safari-web-extension-converter');
    process.exit(1);
  }
  if (problems.length) {
    console.error('\n✗ 有补丁没打上 —— 装出来的 App 会缺功能，而 Xcode 不会说任何话：');
    for (const x of problems) console.error('  ' + x);
    process.exit(1);
  }

  console.log('\n注意：Xcode 增量构建不一定会重拷改动过的资源。测 App 资源前先 rm -rf derivedData。');
}

if (require.main === module) main();

module.exports = {
  classifyProject, patchViewController, patchMacWindowXml, patchMacMenuXml,
  patchAudioBridgeSwift, patchPlistXml, patchInfoPlists, PLIST_KEYS,
};
